package com.flipkart.grayskull.audit.mysql.entity;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;
import org.springframework.data.domain.Persistable;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;

/**
 * One audit event in MySQL. Rows are only ever inserted.
 * <p>
 * The id is assigned by the application ({@link com.flipkart.grayskull.audit.mysql.AuditEventIds}), not generated by
 * the database, so Hibernate can batch inserts; {@link #isNew()} is always true so Spring Data inserts directly
 * instead of selecting first. Duplicates are filtered before insert by {@code MysqlAuditStore}.
 */
@Entity
@Table(name = "audit_entry")
@IdClass(AuditRowId.class)
@Getter
@Setter
@NoArgsConstructor
public class AuditEntryRow implements Persistable<AuditRowId> {

    @Id
    @Column(name = "id", columnDefinition = "BINARY(16)")
    private UUID rowId;

    /** Event time; all sorting and paging use it. */
    @Id
    @Column(name = "ts")
    private Instant ts;

    /** Idempotency key the row id is derived from (outbox id or Derby log id). */
    @Column(name = "event_id")
    private String eventId;

    @Column(name = "project_id")
    private String projectId;

    @Column(name = "resource_type")
    private String resourceType;

    @Column(name = "resource_name")
    private String resourceName;

    @Column(name = "resource_version")
    private Integer resourceVersion;

    @Column(name = "action")
    private String action;

    @Column(name = "user_id")
    private String userId;

    /** SERVICE, HUMAN or OTHER, derived from the user id prefix at insert time. */
    @Column(name = "user_type")
    private String userType;

    @Column(name = "actor_id")
    private String actorId;

    @JdbcTypeCode(SqlTypes.JSON)
    @Column(name = "ips")
    private Map<String, String> ips;

    @JdbcTypeCode(SqlTypes.JSON)
    @Column(name = "metadata")
    private Map<String, String> metadata;

    /** Arrival time in MySQL, set by the database. */
    @Column(name = "created_at", insertable = false, updatable = false)
    private Instant createdAt;

    @Override
    public AuditRowId getId() {
        return new AuditRowId(rowId, ts);
    }

    @Override
    public boolean isNew() {
        return true;
    }
}
